-- AP world language courses share one framework.
--
-- The six language and culture courses (Spanish, French, German, Italian,
-- Japanese, Chinese) are all built on the same six themes, so the sheet listed
-- them once and the importer read only a handful of rows per course. They came
-- out with six subtopics each, which is a parsing artefact rather than a small
-- course.
--
-- Seeded here in full instead. "[Language] in the World" is substituted per
-- course, so AP Spanish gets "Spanish in the World" rather than a placeholder.

BEGIN;

-- Clear the partial rows first so the count is right rather than merged.
DELETE FROM syllabus_content
WHERE curriculum = 'AP' AND subject LIKE 'AP % Language and Culture';

ON CONFLICT DO NOTHING;

COMMIT;
